package com.citacloud.springboot.contacloud.app.services;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.security.PrintAgentPrincipal;
import java.lang.reflect.Field;
import java.security.SecureRandom;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;

class PrintAgentPairingServiceTest {
    private final VinculacionAgenteImpresionRepository pairings=mock(VinculacionAgenteImpresionRepository.class);
    private final AgenteImpresionRepository agents=mock(AgenteImpresionRepository.class);
    private final CredencialAgenteImpresionRepository credentials=mock(CredencialAgenteImpresionRepository.class);
    private final EmpresaRepository companies=mock(EmpresaRepository.class);private final SucursalRepository branches=mock(SucursalRepository.class);
    private final PrintAgentTokenService tokens=new PrintAgentTokenService(new byte[32],new SecureRandom());private final AuditoriaService audit=mock(AuditoriaService.class);
    private final PrintAgentPairingService service=new PrintAgentPairingService(mock(CashRegisterRepository.class),pairings,agents,credentials,companies,branches,tokens,audit,Duration.ofMinutes(15),Duration.ofDays(30),Duration.ofMinutes(1),5);
    private UUID tenant,company,branch,agentId,user;private AgenteImpresion agent;
    @BeforeEach void setup(){tenant=UUID.randomUUID();company=UUID.randomUUID();branch=UUID.randomUUID();agentId=UUID.randomUUID();user=UUID.randomUUID();agent=new AgenteImpresion(tenant,company,branch,"PA-000001","POS Caja Principal",user);set(agent,"id",agentId);when(agents.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));when(pairings.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));when(credentials.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));}
    @Test void pairingValidoActivaAgenteConsumeCodigoYCreaCredencial(){String code="847291";var pairing=new VinculacionAgenteImpresion(tenant,company,agentId,tokens.hashCodigo(code),OffsetDateTime.now().plusMinutes(10),user);var ref=mock(VinculacionAgenteImpresionRepository.Referencia.class);when(ref.getAgenteId()).thenReturn(agentId);when(ref.getTenantId()).thenReturn(tenant);when(pairings.findByHashCodigo(tokens.hashCodigo(code))).thenReturn(Optional.of(ref));when(agents.bloquearAgente(agentId,tenant)).thenReturn(Optional.of(agent));when(pairings.bloquearPorHash(tokens.hashCodigo(code))).thenReturn(Optional.of(pairing));when(agents.bloquearAgente(agentId,tenant)).thenReturn(Optional.of(agent));TokenAgenteImpresionDto result=service.vincular(new PairingAgenteImpresionInput(code,new PairingAgenteImpresionInput.Dispositivo("CAJA-01","1.0.0","Windows")));assertThat(agent.getEstado()).isEqualTo(EstadoAgenteImpresion.ACTIVE);assertThat(pairing.getConsumidoEn()).isNotNull();assertThat(result.agentId()).isEqualTo(agentId);assertThat(result.accessToken()).doesNotContain(code);ArgumentCaptor<CredencialAgenteImpresion> saved=ArgumentCaptor.forClass(CredencialAgenteImpresion.class);verify(credentials).saveAndFlush(saved.capture());assertThat(saved.getValue().getRevocadaEn()).isNull();verify(audit).registrarPara(eq(company),isNull(),eq("PairingSucceeded"),eq("PrintAgent"),eq(agentId),anyString());}
    @Test void codigoConsumidoEsRechazadoSinCrearOtraCredencial(){String code="111111";var pairing=new VinculacionAgenteImpresion(tenant,company,agentId,tokens.hashCodigo(code),OffsetDateTime.now().plusMinutes(10),user);pairing.consumir(OffsetDateTime.now());var ref=mock(VinculacionAgenteImpresionRepository.Referencia.class);when(ref.getAgenteId()).thenReturn(agentId);when(ref.getTenantId()).thenReturn(tenant);when(pairings.findByHashCodigo(tokens.hashCodigo(code))).thenReturn(Optional.of(ref));when(agents.bloquearAgente(agentId,tenant)).thenReturn(Optional.of(agent));when(pairings.bloquearPorHash(tokens.hashCodigo(code))).thenReturn(Optional.of(pairing));assertThatThrownBy(()->service.vincular(new PairingAgenteImpresionInput(code,new PairingAgenteImpresionInput.Dispositivo(null,null,null)))).isInstanceOf(VinculacionAgenteException.class).hasMessage("No fue posible vincular el dispositivo.");verifyNoInteractions(credentials);}
    @Test void agenteRevocadoNoAutentica(){String access=tokens.nuevoToken(tenant);var credential=new CredencialAgenteImpresion(tenant,company,agentId,tokens.hashAcceso(access),OffsetDateTime.now().plusMinutes(5),tokens.hashRenovacion(tokens.nuevoToken(tenant)),OffsetDateTime.now().plusDays(1),null);agent.revocar(user);when(credentials.findByHashAcceso(tokens.hashAcceso(access))).thenReturn(Optional.of(credential));when(agents.findByIdAndTenantIdAndEmpresaId(agentId,tenant,company)).thenReturn(Optional.of(agent));assertThatThrownBy(()->service.autenticar(access)).isInstanceOf(VinculacionAgenteException.class);}
    @Test void heartbeatSeCoalesceDentroDelIntervalo(){agent.vincular("CAJA-01","1.0","Windows");when(agents.bloquearAgente(agentId,tenant)).thenReturn(Optional.of(agent));service.heartbeat(new PrintAgentPrincipal(agentId,tenant,company,branch,"PA-000001","POS"),"1.0");verify(agents,never()).save(any());}
    @Test void revincularAgenteActivoReemplazaCredencialesSinCrearAgente(){agent.vincular("ANTERIOR","1","Windows");String code="123456";var pairing=new VinculacionAgenteImpresion(tenant,company,agentId,tokens.hashCodigo(code),OffsetDateTime.now().plusMinutes(10),user);var ref=mock(VinculacionAgenteImpresionRepository.Referencia.class);when(ref.getAgenteId()).thenReturn(agentId);when(ref.getTenantId()).thenReturn(tenant);when(pairings.findByHashCodigo(tokens.hashCodigo(code))).thenReturn(Optional.of(ref));when(pairings.bloquearPorHash(tokens.hashCodigo(code))).thenReturn(Optional.of(pairing));when(agents.bloquearAgente(agentId,tenant)).thenReturn(Optional.of(agent));service.vincular(new PairingAgenteImpresionInput(code,new PairingAgenteImpresionInput.Dispositivo("NUEVO","2","Windows")));assertThat(agent.getNombreMaquina()).isEqualTo("NUEVO");verify(credentials).revocarActivas(eq(tenant),eq(company),eq(agentId),any());assertThat(agent.getId()).isEqualTo(agentId);verify(audit).registrarPara(eq(company),isNull(),eq("PrintAgentDeviceReplaced"),eq("PrintAgent"),eq(agentId),anyString());}
    private static void set(Object target,String name,Object value){try{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);field.set(target,value);}catch(ReflectiveOperationException ex){throw new AssertionError(ex);}}
}
